def help_text(label):
    """Return meaningful Streamlit hover help; support dynamic weight labels."""
    key = str(label)
    if key in HELP:
        return HELP[key]
    if key.endswith(" %"):
        component = key[:-2]
        definitions = {
            "Reservoir": "quality and direct log-supported reservoir presence",
            "Structure": "relative structural position; an imperfect proxy, NOT closure",
            "Seismic": "4D contrast discounted by local non-reservoir repeatability",
            "Proximity": "distance to controlled well positions, NOT produced/drained radius",
            "Horizon": "seismic horizon sensitivity/interpretability, NOT geological certainty",
            "Production": "independent production history (UNAVAILABLE unless legitimately supplied)",
        }
        return (f"Weight assigned to {component} evidence (percent of nominal ranking). "
                f"Represents {definitions.get(component, 'this evidence source')}. "
                "All six percentages must sum to 100. Missing components are shown as gaps; "
                "reweighting changes relative ranks, not discovery probability.")
    if key.startswith('Export ') or key.startswith('Download '):
        return f"Save {key.removeprefix('Export ').removeprefix('Download ')} to your computer for reproducible review. Check units, field-data permissions, and processing/QC caveats before distributing."
    if key.startswith('Calculate ') or key.startswith('Build ') or key.startswith('Validate '):
        return f"Execute {key.lower()} using the current inputs. Verify required data and QC flags. Outputs are provisional unless geoscientifically validated."
    if key.startswith('🧭') or key.startswith('🏠') or key.startswith('〰️') or key.startswith('🗺️') or key.startswith('🪨'):
        return f"Navigate to {key} without modifying the underlying seismic, well logs or analysis results."
    return (f"{key}: changes the current dashboard selection or analysis parameters. "
            "Review input units and resulting QC flags; this selection alone does not validate reservoir interpretation.")


